const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType, ShadingType,
  PageBreak
} = require('docx');

// --- Luxora palette ---
const NAVY = "1F2A44";
const GOLD = "8A6E3F";
const SOFT = "F5F1EA";
const RULE = "C8B89A";
const GREY = "555555";

// ----- Helpers -----------------------------------------------------------

const para = (text, opts = {}) => new Paragraph({
  spacing: { before: opts.before ?? 80, after: opts.after ?? 120, line: 320 },
  alignment: opts.align ?? AlignmentType.LEFT,
  children: [new TextRun({
    text, font: "Calibri",
    size: opts.size ?? 22,
    bold: !!opts.bold,
    italics: !!opts.italics,
    color: opts.color ?? "222222",
  })],
});

const sectionLabel = (text) => new Paragraph({
  spacing: { before: 360, after: 60 },
  children: [new TextRun({
    text: text.toUpperCase(),
    font: "Calibri", size: 18, bold: true, color: GOLD, characterSpacing: 40,
  })],
});

const h1 = (text) => new Paragraph({
  spacing: { before: 60, after: 240 },
  children: [new TextRun({ text, font: "Calibri", size: 36, bold: true, color: NAVY })],
});

const h2 = (text) => new Paragraph({
  spacing: { before: 280, after: 120 },
  children: [new TextRun({ text, font: "Calibri", size: 28, bold: true, color: NAVY })],
});

const h3 = (text) => new Paragraph({
  spacing: { before: 220, after: 80 },
  children: [new TextRun({ text, font: "Calibri", size: 22, bold: true, color: NAVY })],
});

const h4 = (text) => new Paragraph({
  spacing: { before: 160, after: 60 },
  children: [new TextRun({ text, font: "Calibri", size: 22, bold: true, color: GOLD })],
});

const bullet = (text) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { before: 40, after: 60, line: 300 },
  children: [new TextRun({ text, font: "Calibri", size: 22, color: "222222" })],
});

const bulletMixed = (lead, rest) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { before: 40, after: 60, line: 300 },
  children: [
    new TextRun({ text: lead, font: "Calibri", size: 22, bold: true, color: "222222" }),
    new TextRun({ text: rest, font: "Calibri", size: 22, color: "222222" }),
  ],
});

const spacer = (size = 120) => new Paragraph({ spacing: { before: size, after: size }, children: [new TextRun("")] });

const pageBreak = () => new Paragraph({ children: [new PageBreak()] });

// Pricing card style box
const card = (titleText, subtitle, lines, priceText) => {
  const cellChildren = [];
  cellChildren.push(new Paragraph({
    spacing: { before: 40, after: 60 },
    children: [new TextRun({ text: titleText.toUpperCase(), font: "Calibri", size: 22, bold: true, color: GOLD, characterSpacing: 60 })],
  }));
  if (subtitle) {
    cellChildren.push(new Paragraph({
      spacing: { before: 0, after: 160 },
      children: [new TextRun({ text: subtitle, font: "Calibri", size: 22, italics: true, color: GREY })],
    }));
  }
  for (const line of lines) {
    cellChildren.push(new Paragraph({
      spacing: { before: 40, after: 40, line: 300 },
      children: [
        new TextRun({ text: "•  ", font: "Calibri", size: 22, color: GOLD, bold: true }),
        new TextRun({ text: line, font: "Calibri", size: 22, color: "222222" }),
      ],
    }));
  }
  if (priceText) {
    cellChildren.push(new Paragraph({
      spacing: { before: 200, after: 40 },
      children: [new TextRun({ text: priceText, font: "Calibri", size: 24, bold: true, color: NAVY })],
    }));
  }

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    borders: {
      top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
      bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
      right: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
      left: { style: BorderStyle.SINGLE, size: 18, color: GOLD },
      insideHorizontal: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
      insideVertical: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
    },
    rows: [new TableRow({
      children: [new TableCell({
        width: { size: 9360, type: WidthType.DXA },
        shading: { fill: SOFT, type: ShadingType.CLEAR },
        margins: { top: 240, bottom: 240, left: 320, right: 280 },
        children: cellChildren,
      })],
    })],
  });
};

// AI prompt block: dark code-style background
const promptBlock = (label, promptText) => {
  const cellChildren = [
    new Paragraph({
      spacing: { before: 60, after: 120 },
      children: [new TextRun({ text: label.toUpperCase(), font: "Calibri", size: 18, bold: true, color: GOLD, characterSpacing: 60 })],
    }),
  ];

  // Split prompt into paragraphs by double newline so it formats naturally
  const blocks = promptText.split(/\n\n+/);
  blocks.forEach((blk, idx) => {
    cellChildren.push(new Paragraph({
      spacing: { before: idx === 0 ? 0 : 100, after: 100, line: 300 },
      children: [new TextRun({ text: blk, font: "Calibri", size: 22, color: "1A1A1A" })],
    }));
  });

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    borders: {
      top: { style: BorderStyle.SINGLE, size: 6, color: NAVY },
      bottom: { style: BorderStyle.SINGLE, size: 6, color: NAVY },
      left: { style: BorderStyle.SINGLE, size: 6, color: NAVY },
      right: { style: BorderStyle.SINGLE, size: 6, color: NAVY },
      insideHorizontal: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
      insideVertical: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
    },
    rows: [new TableRow({
      children: [new TableCell({
        width: { size: 9360, type: WidthType.DXA },
        shading: { fill: "F8F4EC", type: ShadingType.CLEAR },
        margins: { top: 280, bottom: 280, left: 320, right: 320 },
        children: cellChildren,
      })],
    })],
  });
};

// Two-column comparison table (light, used for value stacks)
const valueStackTable = (rows) => {
  const headerRow = new TableRow({
    tableHeader: true,
    children: ["INCLUSION", "STAND-ALONE VALUE"].map(t => new TableCell({
      width: { size: t === "INCLUSION" ? 6500 : 2860, type: WidthType.DXA },
      shading: { fill: NAVY, type: ShadingType.CLEAR },
      margins: { top: 120, bottom: 120, left: 160, right: 160 },
      borders: {
        top: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
        bottom: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
        left: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
        right: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
      },
      children: [new Paragraph({
        children: [new TextRun({ text: t, font: "Calibri", size: 18, bold: true, color: "FFFFFF", characterSpacing: 40 })],
      })],
    })),
  });

  const dataRows = rows.map((r, idx) => {
    const fill = idx % 2 === 0 ? "FFFFFF" : SOFT;
    return new TableRow({
      children: [
        new TableCell({
          width: { size: 6500, type: WidthType.DXA },
          shading: { fill, type: ShadingType.CLEAR },
          margins: { top: 140, bottom: 140, left: 180, right: 180 },
          borders: {
            top: { style: BorderStyle.SINGLE, size: 2, color: RULE },
            bottom: { style: BorderStyle.SINGLE, size: 2, color: RULE },
            left: { style: BorderStyle.SINGLE, size: 2, color: RULE },
            right: { style: BorderStyle.SINGLE, size: 2, color: RULE },
          },
          children: [new Paragraph({
            spacing: { line: 280 },
            children: [new TextRun({ text: r[0], font: "Calibri", size: 20, color: "222222" })],
          })],
        }),
        new TableCell({
          width: { size: 2860, type: WidthType.DXA },
          shading: { fill, type: ShadingType.CLEAR },
          margins: { top: 140, bottom: 140, left: 180, right: 180 },
          borders: {
            top: { style: BorderStyle.SINGLE, size: 2, color: RULE },
            bottom: { style: BorderStyle.SINGLE, size: 2, color: RULE },
            left: { style: BorderStyle.SINGLE, size: 2, color: RULE },
            right: { style: BorderStyle.SINGLE, size: 2, color: RULE },
          },
          children: [new Paragraph({
            alignment: AlignmentType.RIGHT,
            spacing: { line: 280 },
            children: [new TextRun({ text: r[1], font: "Calibri", size: 20, bold: true, color: NAVY })],
          })],
        }),
      ],
    });
  });

  // Total row
  const totalRow = (label, value) => new TableRow({
    children: [
      new TableCell({
        width: { size: 6500, type: WidthType.DXA },
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        margins: { top: 140, bottom: 140, left: 180, right: 180 },
        borders: {
          top: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
          bottom: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
          left: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
          right: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
        },
        children: [new Paragraph({
          children: [new TextRun({ text: label, font: "Calibri", size: 22, bold: true, color: "FFFFFF" })],
        })],
      }),
      new TableCell({
        width: { size: 2860, type: WidthType.DXA },
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        margins: { top: 140, bottom: 140, left: 180, right: 180 },
        borders: {
          top: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
          bottom: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
          left: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
          right: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
        },
        children: [new Paragraph({
          alignment: AlignmentType.RIGHT,
          children: [new TextRun({ text: value, font: "Calibri", size: 22, bold: true, color: "FFFFFF" })],
        })],
      }),
    ],
  });

  return { table: new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [6500, 2860],
    rows: [headerRow, ...dataRows],
  }), totalRow };
};

// Build a value stack table with a total row appended
const valueStack = (rows, totalLabel, totalValue) => {
  const { table, totalRow } = valueStackTable(rows);
  // Re-build with the total row included
  const headerRow = table.root[0];
  const dataRows = table.root.slice(1);
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [6500, 2860],
    rows: [headerRow, ...dataRows, totalRow(totalLabel, totalValue)],
  });
};

// Three-tier membership table (side by side)
const tierTable = (tiers) => {
  const colWidth = Math.floor(9360 / tiers.length);

  const headerRow = new TableRow({
    tableHeader: true,
    children: tiers.map(t => new TableCell({
      width: { size: colWidth, type: WidthType.DXA },
      shading: { fill: NAVY, type: ShadingType.CLEAR },
      margins: { top: 200, bottom: 200, left: 180, right: 180 },
      borders: {
        top: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
        bottom: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
        left: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
        right: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
      },
      children: [
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { after: 60 },
          children: [new TextRun({ text: t.name.toUpperCase(), font: "Calibri", size: 20, bold: true, color: "FFFFFF", characterSpacing: 60 })],
        }),
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { before: 0 },
          children: [new TextRun({ text: t.price, font: "Calibri", size: 24, bold: true, color: GOLD })],
        }),
      ],
    })),
  });

  // Body row with bulleted lists
  const bodyRow = new TableRow({
    children: tiers.map(t => {
      const cellKids = [
        new Paragraph({
          spacing: { after: 120 },
          children: [new TextRun({ text: t.tagline, font: "Calibri", size: 20, italics: true, color: GREY })],
        }),
      ];
      for (const item of t.includes) {
        cellKids.push(new Paragraph({
          spacing: { before: 40, after: 40, line: 280 },
          children: [
            new TextRun({ text: "✓  ", font: "Calibri", size: 20, bold: true, color: GOLD }),
            new TextRun({ text: item, font: "Calibri", size: 20, color: "222222" }),
          ],
        }));
      }
      cellKids.push(new Paragraph({
        spacing: { before: 200 },
        children: [new TextRun({ text: t.idealFor, font: "Calibri", size: 18, italics: true, color: GREY })],
      }));
      return new TableCell({
        width: { size: colWidth, type: WidthType.DXA },
        shading: { fill: SOFT, type: ShadingType.CLEAR },
        margins: { top: 220, bottom: 220, left: 200, right: 200 },
        borders: {
          top: { style: BorderStyle.SINGLE, size: 2, color: RULE },
          bottom: { style: BorderStyle.SINGLE, size: 2, color: RULE },
          left: { style: BorderStyle.SINGLE, size: 2, color: RULE },
          right: { style: BorderStyle.SINGLE, size: 2, color: RULE },
        },
        children: cellKids,
      });
    }),
  });

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: tiers.map(() => colWidth),
    rows: [headerRow, bodyRow],
  });
};

// ----- Content -----------------------------------------------------------

const children = [];

// ===== COVER PAGE ========================================================

children.push(new Paragraph({ spacing: { before: 1800 }, children: [new TextRun("")] }));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 60 },
  children: [new TextRun({
    text: "THE LUXORA COLLECTIVE",
    font: "Calibri", size: 26, bold: true, color: NAVY, characterSpacing: 80,
  })],
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 120, after: 480 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 6 } },
  children: [new TextRun({ text: "                              ", font: "Calibri", size: 22 })],
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 60 },
  children: [new TextRun({ text: "PLAYBOOK", font: "Calibri", size: 18, bold: true, color: GOLD, characterSpacing: 80 })],
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
