children.push(para("theluxoracollective.co", { color: GREY, italics: true, before: 0 }));
children.push(para("go.theluxoracollective.co/the-luxora-growth-engine", { color: GREY, italics: true, before: 0 }));

// ----- Document assembly -------------------------------------------------

const doc = new Document({
