  // Body row with bulleted lists
  const bodyRow = new TableRow({
    children: tiers.map(t => {
      const cellKids = [
        new Paragraph({
          spacing: { after: 120 },
          children: [new TextRun({ text: t.tagline, font: "Calibri", size: 20, italics: true, color: GREY })],
        }),
      ];
      for (const item of t.includes) {
        cellKids.push(new Paragraph({
          spacing: { before: 40, after: 40, line: 280 },
