  children: [new TextRun({ text: "PLAYBOOK", font: "Calibri", size: 18, bold: true, color: GOLD, characterSpacing: 80 })],
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 120 },
  children: [new TextRun({
    text: "The Longevity & Wellness Stack",
    font: "Calibri", size: 40, bold: true, color: NAVY,
  })],
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 600 },
  children: [new TextRun({
    text: "Memberships, packages, and consult frameworks built around peptides, GLP-1s, gut health, skin glow, and tanning protocols",
    font: "Calibri", size: 22, italics: true, color: GREY,
  })],
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 240, after: 240 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: RULE, space: 6 } },
  children: [new TextRun({ text: "                              ", font: "Calibri", size: 22 })],
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
