}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 40 },
  children: [new TextRun({ text: "The Luxora Collective", font: "Calibri", size: 22, color: "222222" })],
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 40 },
  children: [new TextRun({ text: "theluxoracollective.co", font: "Calibri", size: 22, italics: true, color: GREY })],
