{"language": "javascript", "code": "const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType, ShadingType,
  PageBreak, Header, Footer, PageNumber
} = require('docx');

// --- Luxora palette ---
const NAVY = "1F2A44";
const GOLD = "8A6E3F";
const SOFT = "F5F1EA";
const RULE = "C8B89A";
const GREY = "555555";

// ----- Builders ----------------------------------------------------------

const para = (text, opts = {}) => new Paragraph({
  spacing: { before: opts.before ?? 80, after: opts.after ?? 120, line: 320 },
  alignment: opts.align ?? AlignmentType.LEFT,
  children: [new TextRun({
    text,
    font: "Calibri",
    size: opts.size ?? 22,
    bold: !!opts.bold,
    italics: !!opts.italics,
    color: opts.color ?? "222222",
  })],
});

const sectionLabel = (text) => new Paragraph({
  spacing: { before: 360, after: 60 },
  children: [new TextRun({
    text: text.toUpperCase(),
    font: "Calibri", size: 18, bold: true, color: GOLD, characterSpacing: 40,
  })],
});

const h1 = (text) => new Paragraph({
  spacing: { before: 60, after: 240 },
  children: [new TextRun({ text, font: "Calibri", size: 36, bold: true, color: NAVY })],
});

const h2 = (text) => new Paragraph({
  spacing: { before: 320, after: 140 },
  children: [new TextRun({ text, font: "Calibri", size: 28, bold: true, color: NAVY })],
});

const h3 = (text) => new Paragraph({
  spacing: { before: 220, after: 80 },
  children: [new TextRun({ text, font: "Calibri", size: 22, bold: true, color: NAVY })],
});

const h4 = (text) => new Paragraph({
  spacing: { before: 180, after: 60 },
  children: [new TextRun({ text, font: "Calibri", size: 22, bold: true, color: GOLD })],
});

const bullet = (text) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { before: 40, after: 60, line: 300 },
  children: [new TextRun({ text, font: "Calibri", size: 22, color: "222222" })],
});

const bulletMixed = (lead, rest) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { before: 40, after: 60, line: 300 },
  children: [
    new TextRun({ text: lead, font: "Calibri", size: 22, bold: true, color: "222222" }),
    new TextRun({ text: rest, font: "Calibri", size: 22, color: "222222" }),
  ],
});

const numItem = (text) => new Paragraph({
  numbering: { reference: "numbers", level: 0 },
  spacing: { before: 40, after: 60, line: 300 },
  children: [new TextRun({ text, font: "Calibri", size: 22, color: "222222" })],
});

const spacer = (size = 120) => new Paragraph({ spacing: { before: size, after: size }, children: [new TextRun("")] });

const pageBreak = () => new Paragraph({ children: [new PageBreak()] });

const callout = (lines) => {
  const cellChildren = lines.map((line, i) => new Paragraph({
    spacing: { before: i === 0 ? 80 : 40, after: i === lines.length - 1 ? 80 : 40, line: 300 },
    children: [new TextRun({
      text: line.t,
      font: "Calibri",
      size: line.size ?? 22,
      bold: !!line.bold,
      italics: line.italics ?? false,
      color: line.color ?? "333333",
    })],
  }));

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    borders: {
      top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
      bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
      right: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
      left: { style: BorderStyle.SINGLE, size: 18, color: GOLD },
      insideHorizontal: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
      insideVertical: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
    },
    rows: [new TableRow({
      children: [new TableCell({
        width: { size: 9360, type: WidthType.DXA },
        shading: { fill: SOFT, type: ShadingType.CLEAR },
        margins: { top: 200, bottom: 200, left: 280, right: 240 },
        children: cellChildren,
      })],
    })],
  });
};

// Pricing/package card: title bar + body
const card = (title, subtitle, bodyLines) => {
  const headerCell = new TableCell({
    width: { size: 9360, type: WidthType.DXA },
    shading: { fill: NAVY, type: ShadingType.CLEAR },
    margins: { top: 160, bottom: 160, left: 240, right: 240 },
    borders: {
      top: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
      bottom: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
      left: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
      right: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
    },
    children: [
      new Paragraph({
        spacing: { after: 40 },
        children: [new TextRun({ text: title, font: "Calibri", size: 26, bold: true, color: "FFFFFF" })],
      }),
      new Paragraph({
        children: [new TextRun({ text: subtitle, font: "Calibri", size: 20, italics: true, color: "E5DCC2" })],
      }),
    ],
  });

  const bodyChildren = bodyLines.map((line, i) => {
    if (line.kind === "label") {
      return new Paragraph({
        spacing: { before: i === 0 ? 40 : 140, after: 40, line: 300 },
        children: [new TextRun({ text: line.t.toUpperCase(), font: "Calibri", size: 18, bold: true, color: GOLD, characterSpacing: 40 })],
      });
    }
    if (line.kind === "bullet") {
      return new Paragraph({
        numbering: { reference: "bullets", level: 0 },
        spacing: { before: 30, after: 50, line: 300 },
        children: [new TextRun({ text: line.t, font: "Calibri", size: 22, color: "222222" })],
      });
    }
    if (line.kind === "bulletMixed") {
      return new Paragraph({
        numbering: { reference: "bullets", level: 0 },
        spacing: { before: 30, after: 50, line: 300 },
        children: [
          new TextRun({ text: line.lead, font: "Calibri", size: 22, bold: true, color: "222222" }),
          new TextRun({ text: line.rest, font: "Calibri", size: 22, color: "222222" }),
        ],
      });
    }
    if (line.kind === "price") {
      return new Paragraph({
        spacing: { before: 120, after: 60 },
        children: [
          new TextRun({ text: line.label + "  ", font: "Calibri", size: 22, bold: true, color: GOLD }),
          new TextRun({ text: line.value, font: "Calibri", size: 22, color: "222222" }),
        ],
      });
    }
    return new Paragraph({
      spacing: { before: i === 0 ? 40 : 80, after: 80, line: 300 },
      children: [new TextRun({ text: line.t, font: "Calibri", size: 22, color: "222222", italics: !!line.italics })],
    });
  });

  const bodyCell = new TableCell({
    width: { size: 9360, type: WidthType.DXA },
    shading: { fill: "FFFFFF", type: ShadingType.CLEAR },
    margins: { top: 220, bottom: 220, left: 280, right: 280 },
    borders: {
      top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
      bottom: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
      left: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
      right: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
    },
    children: bodyChildren,
  });

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({ children: [headerCell] }),
      new TableRow({ children: [bodyCell] }),
    ],
  });
};

// AI Prompt block — monospace-feeling block on soft background
const promptBlock = (label, useCase, prompt) => {
  const labelPara = new Paragraph({
    spacing: { after: 60 },
    children: [new TextRun({
      text: label.toUpperCase(),
      font: "Calibri", size: 18, bold: true, color: GOLD, characterSpacing: 40,
    })],
  });

  const usePara = new Paragraph({
    spacing: { after: 100, line: 300 },
    children: [
      new TextRun({ text: "When to use it: ", font: "Calibri", size: 22, bold: true, color: NAVY }),
      new TextRun({ text: useCase, font: "Calibri", size: 22, color: "222222" }),
    ],
  });

  const promptParas = prompt.split("\n").map((line, i, arr) => new Paragraph({
    spacing: { before: i === 0 ? 40 : 0, after: i === arr.length - 1 ? 40 : 0, line: 280 },
    children: [new TextRun({
      text: line || " ",
      font: "Consolas",
      size: 20,
      color: "222222",
    })],
  }));

  const promptCell = new TableCell({
    width: { size: 9360, type: WidthType.DXA },
    shading: { fill: SOFT, type: ShadingType.CLEAR },
    margins: { top: 200, bottom: 200, left: 280, right: 280 },
    borders: {
      top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
      bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
      right: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
