const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType, ShadingType,
  PageBreak
} = require('docx');

// --- Color palette (Luxora navy + gold) ---
const NAVY = "1F2A44";
const GOLD = "8A6E3F";
const SOFT = "F5F1EA";
const RULE = "C8B89A";
const GREY = "555555";
const DARK = "1A1A1A";

// ----- Helpers -----------------------------------------------------------

const para = (text, opts = {}) => new Paragraph({
  spacing: { before: opts.before ?? 80, after: opts.after ?? 120, line: 320 },
  alignment: opts.align ?? AlignmentType.LEFT,
  children: [new TextRun({
    text,
    font: "Calibri",
    size: opts.size ?? 22,
    bold: !!opts.bold,
    italics: !!opts.italics,
    color: opts.color ?? DARK,
  })],
});

const sectionLabel = (text) => new Paragraph({
  spacing: { before: 360, after: 60 },
  children: [new TextRun({
    text: text.toUpperCase(),
    font: "Calibri", size: 18, bold: true, color: GOLD, characterSpacing: 40,
  })],
});

const h1 = (text) => new Paragraph({
  spacing: { before: 60, after: 240 },
  children: [new TextRun({ text, font: "Calibri", size: 36, bold: true, color: NAVY })],
});

const h2 = (text) => new Paragraph({
  spacing: { before: 280, after: 120 },
  children: [new TextRun({ text, font: "Calibri", size: 28, bold: true, color: NAVY })],
});

const h3 = (text) => new Paragraph({
  spacing: { before: 220, after: 80 },
  children: [new TextRun({ text, font: "Calibri", size: 22, bold: true, color: NAVY })],
});

const h4 = (text) => new Paragraph({
  spacing: { before: 160, after: 60 },
  children: [new TextRun({ text, font: "Calibri", size: 22, bold: true, color: GOLD })],
});

const bullet = (text) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { before: 40, after: 60, line: 300 },
  children: [new TextRun({ text, font: "Calibri", size: 22, color: DARK })],
});

const bulletMixed = (lead, rest) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { before: 40, after: 60, line: 300 },
  children: [
    new TextRun({ text: lead, font: "Calibri", size: 22, bold: true, color: DARK }),
    new TextRun({ text: rest, font: "Calibri", size: 22, color: DARK }),
  ],
});

const numbered = (text) => new Paragraph({
  numbering: { reference: "numbers", level: 0 },
  spacing: { before: 40, after: 60, line: 300 },
  children: [new TextRun({ text, font: "Calibri", size: 22, color: DARK })],
});

const numberedMixed = (lead, rest) => new Paragraph({
  numbering: { reference: "numbers", level: 0 },
  spacing: { before: 40, after: 60, line: 300 },
  children: [
    new TextRun({ text: lead, font: "Calibri", size: 22, bold: true, color: DARK }),
    new TextRun({ text: rest, font: "Calibri", size: 22, color: DARK }),
  ],
});

const spacer = (size = 120) => new Paragraph({ spacing: { before: size, after: size }, children: [new TextRun("")] });

const pageBreak = () => new Paragraph({ children: [new PageBreak()] });

// Soft callout box with gold left rule
const callout = (lines) => {
  const cellChildren = lines.map((line, i) => new Paragraph({
    spacing: { before: i === 0 ? 80 : 40, after: i === lines.length - 1 ? 80 : 40, line: 300 },
    children: [new TextRun({
      text: line.t,
      font: "Calibri",
      size: line.size ?? 22,
      bold: !!line.bold,
      italics: line.italics ?? false,
      color: line.color ?? "333333",
    })],
  }));

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    borders: {
      top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
      bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
      right: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
      left: { style: BorderStyle.SINGLE, size: 18, color: GOLD },
      insideHorizontal: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
      insideVertical: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
    },
    rows: [new TableRow({
      children: [new TableCell({
        width: { size: 9360, type: WidthType.DXA },
        shading: { fill: SOFT, type: ShadingType.CLEAR },
        margins: { top: 200, bottom: 200, left: 280, right: 240 },
        children: cellChildren,
      })],
    })],
  });
};

// Membership tier card (full-width table with navy header)
const tierCard = ({ name, tagline, price, billing, includes, idealFor, monthlyValue }) => {
  const headerCell = new TableCell({
    width: { size: 9360, type: WidthType.DXA },
    shading: { fill: NAVY, type: ShadingType.CLEAR },
    margins: { top: 220, bottom: 180, left: 280, right: 280 },
    borders: {
      top: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
      bottom: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
      left: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
      right: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
    },
    children: [
      new Paragraph({
        spacing: { after: 60 },
        children: [new TextRun({ text: name, font: "Calibri", size: 28, bold: true, color: "FFFFFF" })],
      }),
      new Paragraph({
        spacing: { after: 80 },
        children: [new TextRun({ text: tagline, font: "Calibri", size: 20, italics: true, color: "F0E6CF" })],
      }),
      new Paragraph({
        children: [
          new TextRun({ text: price, font: "Calibri", size: 30, bold: true, color: "FFFFFF" }),
          new TextRun({ text: "  " + billing, font: "Calibri", size: 20, color: "F0E6CF" }),
        ],
      }),
    ],
  });

  const bodyChildren = [];
  bodyChildren.push(new Paragraph({
    spacing: { before: 80, after: 60 },
    children: [new TextRun({ text: "WHAT'S INCLUDED", font: "Calibri", size: 18, bold: true, color: GOLD, characterSpacing: 40 })],
  }));
  includes.forEach(line => {
    bodyChildren.push(new Paragraph({
      numbering: { reference: "bullets", level: 0 },
      spacing: { before: 30, after: 50, line: 280 },
      children: [new TextRun({ text: line, font: "Calibri", size: 21, color: DARK })],
    }));
  });
  bodyChildren.push(new Paragraph({
    spacing: { before: 160, after: 40 },
    children: [
      new TextRun({ text: "IDEAL FOR:  ", font: "Calibri", size: 18, bold: true, color: GOLD, characterSpacing: 40 }),
      new TextRun({ text: idealFor, font: "Calibri", size: 21, color: DARK }),
    ],
  }));
  if (monthlyValue) {
    bodyChildren.push(new Paragraph({
      spacing: { before: 40, after: 40 },
      children: [
        new TextRun({ text: "STACK VALUE:  ", font: "Calibri", size: 18, bold: true, color: GOLD, characterSpacing: 40 }),
        new TextRun({ text: monthlyValue, font: "Calibri", size: 21, color: DARK }),
      ],
    }));
  }

  const bodyCell = new TableCell({
    width: { size: 9360, type: WidthType.DXA },
    shading: { fill: "FFFFFF", type: ShadingType.CLEAR },
    margins: { top: 180, bottom: 220, left: 280, right: 280 },
    borders: {
      top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
      bottom: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
      left: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
      right: { style: BorderStyle.SINGLE, size: 4, color: NAVY },
    },
    children: bodyChildren,
  });

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({ children: [headerCell] }),
      new TableRow({ children: [bodyCell] }),
    ],
  });
};

// Package combo card (gold accent, lighter feel)
const packageCard = ({ name, hero, components, price, retailValue, savings, who }) => {
  const headerCell = new TableCell({
    width: { size: 9360, type: WidthType.DXA },
    shading: { fill: SOFT, type: ShadingType.CLEAR },
    margins: { top: 200, bottom: 160, left: 280, right: 280 },
    borders: {
      top: { style: BorderStyle.SINGLE, size: 4, color: GOLD },
      bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
      left: { style: BorderStyle.SINGLE, size: 4, color: GOLD },
      right: { style: BorderStyle.SINGLE, size: 4, color: GOLD },
    },
    children: [
      new Paragraph({
        spacing: { after: 40 },
        children: [new TextRun({ text: name, font: "Calibri", size: 26, bold: true, color: NAVY })],
      }),
      new Paragraph({
        spacing: { after: 0 },
        children: [new TextRun({ text: hero, font: "Calibri", size: 20, italics: true, color: GREY })],
      }),
    ],
  });

  const bodyChildren = [];
  bodyChildren.push(new Paragraph({
    spacing: { before: 60, after: 60 },
    children: [new TextRun({ text: "STACK COMPONENTS", font: "Calibri", size: 18, bold: true, color: GOLD, characterSpacing: 40 })],
  }));
  components.forEach(line => {
    bodyChildren.push(new Paragraph({
