children.push(sectionLabel("Section three"));
children.push(h1("Consult frameworks"));
children.push(para("Three consult formats. Match the format to the patient. Don't try to sell a $5K longevity stack in a 15-minute Botox consult.", { italics: true, color: GREY }));

// --- Consult 1: The Discovery ---
children.push(h2("Consult one: The Discovery (15–20 minutes)"));
children.push(para("Use for: walk-ins, single-service inbound leads, low-friction first touch.", { italics: true, color: GREY }));

children.push(h4("Phase 1 — Greeting & Goal (3 minutes)"));
children.push(bullet("\"What brought you in today?\""));
children.push(bullet("\"If we got this exactly right, what would change for you?\""));
children.push(bullet("\"What's stopped you from doing something about this before now?\""));

children.push(h4("Phase 2 — Quick Assessment (5 minutes)"));
children.push(bullet("Skin, body, or symptom check based on what they came in for"));
children.push(bullet("Two qualifying questions: lifestyle (sleep, stress, gut, energy), and history (past treatments, what worked, what didn't)"));

children.push(h4("Phase 3 — Education & Stack Hint (5 minutes)"));
children.push(bullet("Explain what you'd recommend for the surface concern"));
children.push(bullet("Plant one stack hint: \"What you came in for is the surface. There's usually a layer underneath we'd want to look at if you're serious about lasting results.\""));
children.push(bullet("Offer two next steps: book the surface treatment today, or book a 45-minute Stack Build to look deeper"));

children.push(h4("Phase 4 — Close (5 minutes)"));
children.push(bullet("Book the appointment in the room"));
children.push(bullet("Tag the patient in CRM based on stated goals (weight, hormones, gut, glow, longevity)"));
children.push(bullet("Send the relevant package or membership PDF before they leave"));

children.push(spacer(180));

// --- Consult 2: The Stack Build ---
children.push(h2("Consult two: The Stack Build (45–60 minutes)"));
children.push(para("Use for: high-intent patients, package buyers, peptide and longevity inquiries, returning patients ready to commit deeper.", { italics: true, color: GREY }));

children.push(h4("Phase 1 — Welcome & Frame (5 minutes)"));
children.push(bullet("Set expectations: this is not a sales pitch, it's a strategy session"));
children.push(bullet("\"By the end of this conversation, you'll either leave with a clear plan you're excited about, or with the honest answer that this isn't the right fit yet. Either way, you win.\""));
children.push(bullet("Confirm time, environment, and that the patient has full attention (phones away)"));

children.push(h4("Phase 2 — Discovery (15 minutes)"));
children.push(bullet("\"Walk me through your last 12 months. What's shifted?\""));
children.push(bullet("\"What does the next 12 months look like if we don't change anything?\""));
children.push(bullet("\"What does it look like if we get this right?\""));
children.push(bullet("Lifestyle audit: sleep quality, stress, exercise, nutrition style, hormone history, gut symptoms, energy patterns"));
children.push(bullet("Past treatment history: what worked, what didn't, what they swore they'd never do again"));
children.push(bullet("Budget framing: \"To make sure I build a plan that actually works for you, what's the comfort range you'd want me to design within?\""));

children.push(h4("Phase 3 — Stack Build (15 minutes)"));
children.push(bullet("Present the recommended package as a complete stack, not a list of services"));
children.push(bullet("Walk through hero → clinical wrap → supporting stack → tangibles → outcome"));
children.push(bullet("Show retail value, package price, and savings on the page (don't just say it)"));
children.push(bullet("Offer two paths: the full stack, or a shorter starter that keeps the door open"));

children.push(h4("Phase 4 — Objections & Decision (10 minutes)"));
children.push(bullet("Three most common: price, time, fear of needles or peptides"));
children.push(bullet("Price: reframe to monthly cost, financing (Klarna or Affirm), and cost of doing nothing"));
children.push(bullet("Time: walk through realistic appointment cadence — most stacks are 1–2 visits per month"));
children.push(bullet("Fear: provider supervision, lab clearance, and the fact that they can stop anytime"));
children.push(bullet("Decision close: \"Does this feel like the right plan for you, or do you want to adjust before we get started?\""));

children.push(h4("Phase 5 — Booking & Onboarding (10 minutes)"));
children.push(bullet("Book the first 3 appointments in the room"));
children.push(bullet("Take the deposit or full payment"));
children.push(bullet("Hand off to onboarding (CRM tag, intake forms, first-week welcome sequence)"));
children.push(bullet("Confirm the next touchpoint in writing before they leave"));

children.push(spacer(180));

// --- Consult 3: The Reset Review ---
children.push(h2("Consult three: The Reset Review (30 minutes)"));
children.push(para("Use for: stagnant clients, members who have plateaued, patients who finished a 90-day package and need a re-up plan.", { italics: true, color: GREY }));

children.push(h4("Phase 1 — Re-Greet & Wins (5 minutes)"));
children.push(bullet("Pull up before-and-after photos, scan results, lab trends"));
children.push(bullet("Lead with the wins: \"Here's everything that's shifted since you started.\""));
children.push(bullet("\"What feels different to you that I might not see on paper?\""));

children.push(h4("Phase 2 — Gap Analysis (10 minutes)"));
children.push(bullet("\"What's not where you wanted it to be yet?\""));
children.push(bullet("\"What's the one thing that, if it shifted, would matter the most?\""));
children.push(bullet("Identify the next layer: hormones if they did weight, gut if they did glow, longevity if they did performance"));

children.push(h4("Phase 3 — Next-Stack Recommendation (10 minutes)"));
children.push(bullet("Present the appropriate next package or membership upgrade"));
children.push(bullet("Frame as continuation, not a new sale: \"You've built the foundation. This is what we install on top of it.\""));

children.push(h4("Phase 4 — Close (5 minutes)"));
children.push(bullet("Book continuation appointments before they leave"));
children.push(bullet("If they're not ready, downgrade gracefully to a maintenance membership tier"));
children.push(bullet("Tag in CRM for re-touch in 60 days"));

